import re

def differentiate(poly, x):
    if not poly:
        return 0

    terms = re.split(r'(?=[+-])', poly)
    result = 0

    for term in terms:
        if not term or term == '+':
            continue

        # Handle sign at the beginning
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        else:
            sign = 1

        if 'x' not in term:
            continue

        parts = term.split('x')

        # Coefficient part
        coeff_part = parts[0]
        if coeff_part == '' or coeff_part == '+':
            coeff = 1
        elif coeff_part == '-':
            coeff = -1
        else:
            coeff = int(coeff_part)

        # Exponent part
        exp_part = parts[1] if len(parts) > 1 else ''
        if exp_part == '' or exp_part == '^1':
            exponent = 1
        elif exp_part.startswith('^'):
            exponent = int(exp_part[1:])
        else:
            exponent = 1

        # Differentiation rule: d/dx (ax^n) = a*n*x^(n-1)
        if exponent == 0:
            continue

        new_coeff = coeff * exponent
        new_exponent = exponent - 1

        if new_exponent == 0:
            result += sign * new_coeff
        else:
            result += sign * new_coeff * (x ** new_exponent)

    return result
